import java.util.*;
class RiverMeanderTest{public static void main(String[]args){List<RiverRibbon.Point> line=new ArrayList<>();for(int x=0;x<=2000;x+=8)line.add(new RiverRibbon.Point(x,100,16,90));var p=RiverRibbon.smooth(line,83);if(!p.equals(RiverRibbon.smooth(line,83)))throw new AssertionError("Unstable seed");double min=100,max=100,turn=0;int crossings=0;double last=0;for(int i=1;i<p.size()-1;i++){var a=p.get(i-1);var b=p.get(i);var c=p.get(i+1);min=Math.min(min,b.z());max=Math.max(max,b.z());if(b.x()<=a.x())throw new AssertionError("Loop in straight valley");double u=b.z()-100;if(u*last<0)crossings++;if(Math.abs(u)>.01)last=u;double ax=b.x()-a.x(),az=b.z()-a.z(),bx=c.x()-b.x(),bz=c.z()-b.z();turn=Math.max(turn,Math.abs(Math.atan2(ax*bz-az*bx,ax*bx+az*bz)));}if(max-min<45||crossings<6)throw new AssertionError("S bends too weak: "+min+".."+max+" crossings="+crossings);if(turn>.12)throw new AssertionError("Sharp bend "+turn);if(!p.get(0).equals(line.get(0))||!p.get(p.size()-1).equals(line.get(line.size()-1)))throw new AssertionError("Outlet moved");System.out.println("PASS: seeded flowing S bends, span="+(max-min)+", crossings="+crossings+", max turn="+turn);}}
